protocol ForecastSource {
    func temperature(cityID: Int) -> Int?
}
struct DemoForecastSource: ForecastSource {
    func temperature(cityID: Int) -> Int? { cityID == 6 ? 12 : nil }
}
func temperatureText(source: any ForecastSource, cityID: Int) -> String {
    guard let temperature = source.temperature(cityID: cityID) else { return "Нет данных" }
    return "\(temperature) °C"
}
print(temperatureText(source: DemoForecastSource(), cityID: 6))
