protocol TextExporter {
    var label: String { get }
    func export(text: String) -> String
}
struct PlainTextExporter: TextExporter {
    let label = "Обычный текст"
    func export(text: String) -> String { text }
}
struct QuotedTextExporter: TextExporter {
    let label = "Цитата"
    func export(text: String) -> String { "> " + text }
}
func preview(exporter: any TextExporter, text: String) -> String {
    "\(exporter.label): \(exporter.export(text: text))"
}
print(preview(exporter: QuotedTextExporter(), text: "Привет"))

any TextExporter сохраняет доступ к требованиям без привязки к одному типу. Вывод «Цитата: > Привет»; тот же вызов с PlainTextExporter вернул бы исходный текст с его подписью.
